import { Hono } from '/home/jack/rq/2026-10-12-last-push-claude-review-code-sonnet/att-018/clone/src/hono'

const run = async (label: string, mk: () => [string, RequestInit], pre: 'formData' | 'none') => {
  const app = new Hono()
  app.post('/p', async (c) => {
    try {
      if (pre === 'formData') await c.req.formData()
      const body = await c.req.parseBody()
      return c.json({ ok: body })
    } catch (e) {
      return c.json({ err: String(e) }, 500)
    }
  })
  const [url, init] = mk()
  const res = await app.request(url, init)
  console.log(label, res.status, await res.text())
}

const multipart = () => {
  const fd = new FormData(); fd.append('foo', 'bar')
  return ['http://localhost/p', { method: 'POST', body: fd }] as [string, RequestInit]
}
const urlenc = () => {
  const p = new URLSearchParams(); p.append('foo', 'bar')
  return ['http://localhost/p', { method: 'POST', body: p }] as [string, RequestInit]
}
await run('multipart plain parseBody', multipart, 'none')
await run('multipart formData() then parseBody', multipart, 'formData')
await run('urlenc plain parseBody', urlenc, 'none')
await run('urlenc formData() then parseBody', urlenc, 'formData')
EOF
