const buf = await src.arrayBuffer()
for (const h of [ct.replace('multipart/form-data','Multipart/Form-Data'), 'Application/X-WWW-Form-Urlencoded']) {
  const body = h.startsWith('Multipart') ? buf : 'foo=bar'
  try { const r = new Request('http://x/', {method:'POST', body, headers:{'Content-Type':h}}); const f = await r.formData(); console.log(h.slice(0,30), [...f.entries()]) } catch(e){ console.log(h.slice(0,30), 'ERR', String(e)) }
}
console.log(process.version)
